import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, float, color as tslColor } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, CircleGeometry, Color, PointLight, DoubleSide } = THREE;

  const group = new Group();
  group.name = 'collection-stat-tile';
  const cleanups = [];
  const timelines = [];

  const spec = config.intent && config.intent.visualSpec ? config.intent.visualSpec : {};
  const colors = spec.colors || { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };
  const C = {
    ink: new Color(colors.ink || '#16161d'),
    paper: new Color(colors.paper || '#e8ecf2'),
    accent: new Color(colors.accent || '#ff2a38'),
    surface: new Color(colors.surface || '#0b0b10'),
  };

  // ---- Backdrop gradient plane (stage, never void) ----
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: true });
  const gy = smoothstep(float(0), float(1), uv().y);
  backdropMat.colorNode = mix(tslColor(colors.surface || '#0b0b10'), tslColor(colors.ink || '#16161d'), gy);
  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  cleanups.push(() => { backdropMat.dispose(); backdrop.geometry.dispose(); });

  // ---- Contact shadow plane (grounded subject) ----
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const cu = uv();
  const dx = cu.x.sub(0.5);
  const dy = cu.y.sub(0.5);
  const r = dx.mul(dx).add(dy.mul(dy)).sqrt();
  shadowMat.opacityNode = float(1.0).sub(smoothstep(float(0.0), float(0.5), r)).mul(0.55);
  shadowMat.colorNode = tslColor(0x000000);
  const shadowPlane = new Mesh(new CircleGeometry(1.5, 64), shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.set(0, -0.85, 0.0);
  group.add(shadowPlane);
  cleanups.push(() => { shadowMat.dispose(); shadowPlane.geometry.dispose(); });

  // ---- Card base panel: machined surface ----
  const panelMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  const pgy = smoothstep(float(0), float(1), uv().y);
  panelMat.colorNode = mix(tslColor(colors.ink).mul(tslColor(0x1f1f26)), tslColor(colors.ink), pgy);
  // subtle border accent
  const bEdge = smoothstep(float(0.92), float(1.0), cu.x.max(cu.y.sub(0).absOne ? cu.y : cu.y)).add(smoothstep(float(0.0), float(0.02), cu.x.min(cu.y)));
  panelMat.colorNode = mix(panelMat.colorNode, tslColor(colors.accent).mul(0.6), float(0.0));
  const panel = new Mesh(new PlaneGeometry(2.4, 1.5), panelMat);
  panel.position.set(0, 0, -0.05);
  group.add(panel);
  cleanups.push(() => { panelMat.dispose(); panel.geometry.dispose(); });

  // ---- Foreground accent bar (< 10% of frame) ----
  const accentMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  accentMat.colorNode = tslColor(colors.accent || '#ff2a38');
  const accentBar = new Mesh(new PlaneGeometry(1.4, 0.035), accentMat);
  accentBar.position.set(0, -0.5, 0.25);
  group.add(accentBar);
  cleanups.push(() => { accentMat.dispose(); accentBar.geometry.dispose(); });

  // ---- Accent rim light (local, <=1.5) ----
  const rim = new PointLight(colors.accent || '#ff2a38', 1.3, 9, 1.6);
  rim.position.set(-2.2, 0.6, -0.5);
  group.add(rim);
  cleanups.push(() => { if (rim.dispose) rim.dispose(); });

  // ---- Secondary cool fill for metal specular ----
  const coolFill = new PointLight(0xc7cdd6, 0.5, 9, 1.8);
  coolFill.position.set(2.0, -0.3, 1.2);
  group.add(coolFill);
  cleanups.push(() => { if (coolFill.dispose) coolFill.dispose(); });

  // ---- GLB subject ----
  const holder = new Group();
  group.add(holder);

  const baseScale = 0.9;
  const baseY = 0.08;

  if (config.meshUrl && ctx.glbLoader) {
    const p = ctx.glbLoader.loadGLB(config.meshUrl);
    if (p && p.then) {
      p.then((gltf) => {
        const mesh = gltf && gltf.scene ? gltf.scene : gltf;
        if (mesh) {
          mesh.traverse((child) => {
            if (child.isMesh && child.material) {
              const m = child.material;
              if (m.metalness !== undefined) m.metalness = Math.min(m.metalness, 0.5);
              if (m.roughness !== undefined) m.roughness = Math.max(m.roughness, 0.5);
              m.envMapIntensity = 0.8;
            }
          });
          mesh.scale.setScalar(baseScale);
          mesh.position.set(0, baseY, 0.3);
          holder.add(mesh);

          // weighted-settle entrance
          const tl = gsap.timeline();
          tl.from(holder.position, { y: baseY + 0.4, duration: 0.7, ease: 'power3.out' });
          tl.from(holder.scale, { x: 0.55, y: 0.55, z: 0.55, duration: 0.7, ease: 'power3.out' }, 0);
          tl.to(holder.scale, { x: baseScale * 1.04, y: baseScale * 1.04, z: baseScale * 1.04, duration: 0.45, ease: 'power4.out' });
          tl.to(holder.scale, { x: baseScale, y: baseScale, z: baseScale, duration: 0.45, ease: 'power4.out' });
          timelines.push(tl);
        }
      }).catch(() => {});
    }
  }

  // ---- Text (none specified) ----
  const items = config.textContent ?? (config.intent && config.intent.visualSpec && config.intent.visualSpec.textContent) ?? [];
  for (const item of items) {
    if (item && item.text && ctx.fontAtlas && ctx.fontAtlas.createText) {
      const t = ctx.fontAtlas.createText(String(item.text), {
        fontSize: (item.typography && item.typography.fontSize) || 0.14,
        color: (item.role === 'label') ? colors.accent : colors.paper,
        align: 'center'
      });
      if (t) { t.position.set(0, -0.2, 0.3); group.add(t); }
    }
  }

  // ---- Cinematic primitives ----
  const prims = config.cinematicPrimitives || [];
  for (const p of prims) {
    if (ctx.primitives && ctx.primitives[p.name]) {
      try {
        const r = ctx.primitives[p.name](group, p.params || {});
        if (r && r.cleanup) cleanups.push(r.cleanup);
        if (r && r.timeline) timelines.push(r.timeline);
      } catch (e) { /* swallow */ }
    }
  }

  // ---- Handlers ----
  let pressTl = null;
  group.userData.handlers = {
    hover: () => {
      gsap.to(holder.position, { y: baseY + 0.15, duration: 0.5, ease: 'power2.out', overwrite: 'auto' });
      gsap.to(holder.scale, { x: baseScale * 1.03, y: baseScale * 1.03, z: baseScale * 1.03, duration: 0.4, ease: 'power2.out', overwrite: 'auto' });
      gsap.to(rim, { intensity: 1.6, duration: 0.4, ease: 'power2.out', overwrite: 'auto' });
    },
    unhover: () => {
      gsap.to(holder.position, { y: baseY, duration: 0.4, ease: 'power2.out', overwrite: 'auto' });
      gsap.to(holder.scale, { x: baseScale, y: baseScale, z: baseScale, duration: 0.4, ease: 'power2.out', overwrite: 'auto' });
      gsap.to(rim, { intensity: 1.3, duration: 0.4, ease: 'power2.out', overwrite: 'auto' });
    },
    click: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(holder.scale, { x: baseScale * 0.97, y: baseScale * 0.97, z: baseScale * 0.97, duration: 0.12, ease: 'power2.out' });
      pressTl.to(holder.scale, { x: baseScale, y: baseScale, z: baseScale, duration: 0.3, ease: 'back.out(2)' });
      ctx.emit('hub-collection.select', { source: config.id || 'collection-stat-tile' });
    }
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    cleanups.forEach(c => { try { c(); } catch (e) {} });
    timelines.forEach(t => { try { t.kill(); } catch (e) {} });
    if (pressTl) { try { pressTl.kill(); } catch (e) {} }
  };

  return group;
}
